tests.pseudocode:
for _, budget := range []int{100, 500, 1000, 6000} {
  for _, paths := range inputPathSubsets {
    r1, _ := repomap.Build(ctx, ws, budget, paths)
    r2, _ := repomap.Build(ctx, ws, budget, paths)
    assert.Equal(t, r1, r2)
  }
}

obs := &recordingObserver{}
runner := agentrun.Runner{Observer: obs, Verbose: true}
phase := agentrun.Phase{RepoMap: strings.Repeat("x", 400)} // 100 tokens
runner.Run(ctx, phase)
assert.Contains(t, obs.details, "100")

spy := &buildSpy{}
gitSpy := &gitStateSpy{headChanges: false}
pipeline := newFixPipeline(t, spy, gitSpy)
pipeline.Run(ctx)
assert.Equal(t, 1, spy.callCount) // no tree change, no rebuild

gitSpy2 := &gitStateSpy{headChanges: true}
pipeline2 := newFixPipeline(t, spy2, gitSpy2)
pipeline2.Run(ctx)
assert.Equal(t, 2, spy2.callCount) // tree changed, rebuilt

for _, tc := range []struct{budget int; golden string}{
  {6000, "testdata/golden_6000.txt"},
  {1000, "testdata/golden_1000.txt"},
  {300, "testdata/golden_300.txt"},
} {
  result, _ := repomap.Build(ctx, ws, tc.budget, nil)
  expected := readFile(tc.golden)
  assert.Equal(t, expected, result)
}
